import {StrikeClient} from './strike-client.mjs';import {PRIVATE_ROUTES} from './protocol.mjs';import {normalizeAccount,marketSnapshot,resolveFees} from './account-data.mjs';import {assess,recommendLive} from './admission.mjs';import {analyzeMarket,quantityForAmount} from './market-analysis.mjs';import {dec,tierFor} from './risk.mjs';
const $=id=>document.getElementById(id),usd=x=>typeof x==='number'&&Number.isFinite(x)?x.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}):'—',signed=x=>typeof x==='number'&&Number.isFinite(x)?(x>=0?'+':'')+usd(x):'—',time=t=>Number.isFinite(t)?new Date(t).toLocaleTimeString('en-GB'):'—';
let client=new StrikeClient(),bundle=null,side='long',busy=false,revision=0,result=null,market=null,analysis=null,account=null,accountError='需连接真实账户',amountDirty=false;
const labels={time:'官方服务器时间',markets:'市场规则 / 保证金阶梯',mark:'标记价格 / 资金费率',depth:'买卖 20 档订单簿',klines:'最近 60 根 1 分钟标记价 K 线',feeTiers:'公开手续费阶梯',account:'账户余额 / 盈亏 / 可用余额',symbols:'账户各市场生效模式 / 杠杆',positions:'真实持仓',openOrders:'真实挂单',portfolio:'账户费率 / 折扣 / 交易状态',orderHistory:'最近真实订单状态',fillHistory:'最近真实成交'};
const translations={'Fixed-amount stop requires isolated margin; cross or unconfirmed mode is blocked':'固定金额止损必须使用官方已确认的隔离模式。请在 Strike 主应用调整后重新读取。','Confirm isolated margin; cross margin is unsupported in this MVP':'官方当前模式不是隔离，本版不支持全仓新增仓位评估。','Fixed stop amount must be positive':'固定金额预算必须大于 0。','Estimated stop risk exceeds fixed amount':'估计止损风险超过固定金额预算。','Offline fixture: paper execution disabled':'离线数据禁止评估','Market is not open for new exposure':'市场未开放新增风险','Quantity violates official min / max / step':'数量不符合官方最小值、最大值或步长','Below official minimum notional':'低于官方最低名义价值','Above supported margin tier ceiling':'超过官方最大保证金阶梯','Leverage exceeds Guardian or market tier cap':'计划杠杆超过 Guardian 或官方阶梯上限','Stop must be on the loss side of estimated entry':'止损须位于预计入场价的亏损侧','Estimated slippage exceeds 20 bps':'相对标记价的预计成交偏差超过 20 bps','Stop-loss risk exceeds 1% equity budget':'估计止损风险超过真实权益 1% 预算','Total isolated margin exceeds 25% equity':'总保证金占用超过权益 25% 的 Guardian 上限','Insufficient account buying power':'真实可用余额不足','Guardian maximum 3 open positions':'超过 Guardian 最多 3 个持仓的限制','Existing position on this market; net-position changes are unsupported':'本市场已有真实持仓；本版暂不评估加仓或反手','Stop must clear estimated liquidation by 0.5% of mark':'止损距离估计强平价不足标记价 0.5%','Insufficient visible depth for full fill':'可见 20 档深度不足，无法估算完整成交','Invalid order or account values':'订单或账户数值无效；请检查数量、整数杠杆和止损价'};
const tr=s=>translations[s]??(s.startsWith('Invalid data:')?'输入或官方数据格式无效，请检查数量、止损价及金额预算：'+s:s.startsWith('Stale or invalid')?'官方行情或规则快照过期：'+s:s);
function plan(){return {symbol:$('symbol').value,side,quantity:$('quantity').value,leverage:$('leverage').value,stop:$('stop').value,stopMode:$('stopMode').value,stopAmount:$('stopAmount').value,holdingHours:$('holdingHours').value}}
const fresh=packet=>packet?.ok&&Date.now()-packet.at<=15000&&packet.at<=Date.now()+2000;
function node(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n}
function table(target,headers,rows,empty){const root=$(target);root.replaceChildren();if(rows===null){root.append(node('p',empty??'需账户授权 / 官方接口不可用','unavailable'));return}const t=node('table'),head=node('thead'),tr=node('tr');headers.forEach(h=>tr.append(node('th',h)));head.append(tr);t.append(head);const body=node('tbody');if(!rows.length){const td=node('td',empty??'官方返回空列表');td.colSpan=headers.length;const r=node('tr');r.append(td);body.append(r)}else rows.forEach(values=>{const row=node('tr');values.forEach(v=>row.append(node('td',v===undefined||v===null?'—':String(v))));body.append(row)});t.append(body);root.append(t)}
function definition(id,rows){const root=$(id);root.replaceChildren();for(const [name,value]of rows){const r=node('div');r.append(node('dt',name),node('dd',value));root.append(r)}}
function applyAmount(){if(!market)throw Error('需真实市场价格与数量网格');$('quantity').value=quantityForAmount($('amount').value,$('amountBasis').value,$('leverage').value,market.market,market.mark.p);amountDirty=false}
function example(){if(!market)return;$('amount').value='10000';$('amountBasis').value='notional';$('leverage').value='10';applyAmount();const m=market.market,raw=Number(market.mark.p)*(side==='long'?.98:1.02),min=Number(m.order_min_price),tick=Number(m.order_tick_price);$('stop').value=(min+Math.floor((raw-min)/tick)*tick).toFixed(Math.min(m.quote_prec,8));$('actionStatus').textContent='示例：1 万美元名义仓位、10 倍计划杠杆、距当前标记价约 2% 的示例止损。不是交易建议。';render()}
async function reloadSession(){while(busy)await new Promise(resolve=>setTimeout(resolve,50));await load()}
async function load(){if(busy)return;busy=true;const version=revision;$('refresh').disabled=true;$('submit').disabled=true;try{const next=await client.collect($('symbol').value);if(version!==revision)return;bundle=next;try{market=marketSnapshot(bundle);if(!$('quantity').value)applyAmount()}catch{market=null}render()}catch(e){if(version===revision){$('actionStatus').textContent=e.message;bundle=null;market=null;render()}}finally{busy=false;$('refresh').disabled=false;$('submit').disabled=false}}
function render(){const p=bundle?.packets??{};try{market=bundle?marketSnapshot(bundle):null}catch{market=null}account=null;try{account=normalizeAccount(bundle);accountError=''}catch(e){accountError=e.message}
 $('amountField').hidden=$('stopMode').value!=='fixed-amount';const settings=fresh(p.symbols)?p.symbols.data.symbol_settings?.[$('symbol').value]:null;
 $('officialMode').textContent=settings?.margin_mode??'— 需真实账户数据';$('officialLeverage').textContent=settings?.leverage!==undefined?settings.leverage+'×':'— 需真实账户数据';$('useOfficialLeverage').disabled=!settings?.leverage;$('marginBadge').textContent=settings?.margin_mode?.toUpperCase()??'MODE UNKNOWN';
 const fixed=$('stopMode').value==='fixed-amount';$('modeNotice').className='mode-notice'+(settings?.margin_mode==='isolated'?' confirmed':'');$('modeNotice').textContent=settings?.margin_mode==='isolated'?'✓ 官方返回：当前市场为隔离模式。固定金额仍是止损模型预算，不是保证最大损失。':settings?.margin_mode==='cross'?(fixed?'固定金额止损要求隔离模式；Strike 返回当前为全仓，完整评估已拦截。':'Strike 返回当前为全仓，本版暂不支持全仓新增仓位评估。'):'保证金模式尚未从 Strike 核验，完整评估不会放行。';
 let officialEquity=null;try{if(fresh(p.account))officialEquity=Number(dec(p.account.data.wallet_balance)+dec(p.account.data.unrealized_pnl))/1e8}catch{}$('equity').textContent=usd(officialEquity);$('available').textContent=fresh(p.account)?usd(Number(p.account.data.available_balance)):'—';$('budget').textContent=officialEquity===null?'—':usd(officialEquity*.01);$('accountId').textContent=fresh(p.account)?p.account.data.account_id??'ID 缺失':'未核验';$('accountHint').textContent=account?'官方账户快照 · '+time(account.fetchedAt):accountError;
 let serverNow;try{serverNow=client.now()}catch{serverNow=NaN}const isMarketFresh=market&&Number.isFinite(serverNow)&&serverNow-market.mark.E<=15000&&serverNow-(market.depth.T??market.depth.E)<=15000&&fresh(p.markets)&&fresh(p.depth)&&fresh(p.mark);
 $('connection').className='connection'+(isMarketFresh?'':' error');$('connection').textContent=isMarketFresh?`● STRIKE ${client.network.toUpperCase()} / 真实公共行情 · 10 秒轮询 · ${account?'真实账户已核验':'账户未核验，完整评估受限'} · GET ONLY / 不发送订单`:'● 行情尚未就绪、不可用或已过期 · 不使用样例数据替代 · '+(p.mark?.error??'正在读取');$('sourceBadge').textContent=isMarketFresh?'LIVE · REST':'UNAVAILABLE / STALE';
 $('price').textContent=market?usd(Number(market.mark.p)):'—';$('base').textContent=market?.market.base_asset??'—';$('funding').textContent=market?.mark.r!==undefined?(Number(market.mark.r)*100).toFixed(6)+'%':'—';$('spread').textContent=market?usd(Number(market.depth.asks?.[0]?.[0])-Number(market.depth.bids?.[0]?.[0])):'—';$('quoteTime').textContent=market?time(market.mark.E):'—';
 result=assess(bundle,plan());if(result.ok&&!isMarketFresh)result={...result,ok:false,reasons:['官方行情快照已过期']};
 $('guardState').textContent=result.ok?'评估通过':account?'已拦截':'待核验';$('guardState').style.color=result.ok?'var(--mint)':'var(--red)';
 $('verdict').className='verdict'+(result.ok?'':' blocked');$('verdict').replaceChildren(node('strong',result.ok?'✓ 当前规则通过 · 仅评估':'⊘ 完整评估未通过'));const ul=node('ul');for(const r of result.ok?['真实数据检查通过；不保证止损成交或收益']:result.reasons)ul.append(node('li',tr(r)));$('verdict').append(ul);renderActions();
 let officialFees=null;try{if(fresh(p.portfolio))officialFees=resolveFees(p.portfolio.data)}catch{}analysis=null;if(market&&isMarketFresh)try{analysis=analyzeMarket(market,plan(),officialFees,serverNow)}catch{}
 const m=result.metrics;$('riskPct').textContent=m?m.utilization.toFixed(1)+'%':'—';$('riskBar').style.width=m?Math.min(100,m.utilization)+'%':'0%';$('riskBar').style.background=result.ok?'var(--mint)':'var(--red)';
 const values=m?[usd(m.entry),usd(m.notional),usd(m.margin),usd(m.loss),m.liquidation>0?usd(m.liquidation):'无正强平价',m.slippageBps.toFixed(2)+' bps']:analysis?.entry!==null&&analysis?[usd(analysis.entry),usd(analysis.notional),usd(analysis.margin)+' · 计划杠杆假设',analysis.stopLoss!==null?usd(analysis.stopLoss)+(analysis.stopFeesKnown?' · 未含缓冲':' · 仅价差，费率未知'):'—',usd(analysis.liquidation)+' · 隔离假设',analysis.slippageBps.toFixed(2)+' bps']:Array(6).fill('—');document.querySelectorAll('#metrics dd').forEach((el,i)=>el.textContent=values[i]);
 $('submit').textContent=busy?'正在读取…':'重新读取并完整评估 →';drawStress();renderAnalysis(serverNow);renderAccount(p);drawHistory(p);renderSources(p);
}
function renderActions(){const root=$('nextActions');root.replaceChildren();const actions=[];if(!account)actions.push('连接真实账户，并检查「数据来源」中失败或缺失的项目。');else{if(account.marginMode!=='isolated')actions.push('在 Strike 主应用切换当前市场为隔离；已有该市场仓位时，官方不允许直接切换。');if(String(account.leverage)!==$('leverage').value)actions.push('计划杠杆须与官方生效值一致；可采用官方杠杆，超过 10× 仍会被 Guardian 拦截。');if(result?.reasons.some(r=>r.includes('budget')||r.includes('fixed amount')||r.includes('buying power')||r.includes('margin exceeds')))actions.push('缩小计划金额，或使用「推荐合规仓位」；不要用更高杠杆代替减少数量。');if(account.positions.some(p=>p.symbol===$('symbol').value)||account.openOrders.some(o=>o.Symbol===$('symbol').value))actions.push('当前市场已有仓位或挂单。本版只评估新建独立仓位，不会把加仓或反手误作新仓放行。');}if($('stopMode').value==='fixed-amount'&&result?.metrics&&result.metrics.margin>Number($('stopAmount').value))actions.push('预计分配的隔离保证金 '+usd(result.metrics.margin)+' 高于固定止损预算；止损未成交时，损失可能超过该预算。');if(result?.ok)actions.push('通过仅针对本次官方快照。接入 Strike 时，提交前应再次评估并由交易引擎完成最终准入。');for(const a of actions)root.append(node('p',a));}
function drawStress(){const a=analysis;if(!a||a.entry===null){$('chart').replaceChildren();for(const id of ['shockPrice','shockPnl','shockState'])$(id).textContent='—';return}const mark=Number(market.mark.p),shock=Number($('shock').value),q=Number($('quantity').value),dir=side==='long'?1:-1,px=mark*(1+shock/100),pnl=(px-a.entry)*q*dir;let state='无法确定';try{const t=tierFor(market.market,dec((px*q).toFixed(8)));state=a.margin+pnl<=px*q*Number(t.maintenance_margin_rate)-Number(t.maintenance_amount)?'触及维持保证金':'高于维持保证金'}catch{}$('shockLabel').textContent=(shock>=0?'+':'')+shock.toFixed(1)+'%';$('shockPrice').textContent=usd(px);$('shockPnl').textContent=signed(pnl);$('shockPnl').style.color=pnl>=0?'var(--mint)':'var(--red)';$('shockState').textContent=state;$('shockState').style.color=state.startsWith('触及')?'var(--red)':'var(--mint)';
 const maxP=Math.max(mark*.2*q,1),y=v=>120-v/maxP*85,x=v=>55+(v+20)/40*610;let out='<defs><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#b9f879" stop-opacity=".12"/><stop offset="1" stop-color="#b9f879" stop-opacity="0"/></linearGradient></defs>';
 for(let i=-2;i<=2;i++)out+=`<line x1="55" x2="665" y1="${120+i*43}" y2="${120+i*43}" stroke="#25313b" ${i===0?'':'stroke-dasharray="3 5"'}/>`;for(let i=-20;i<=20;i+=10)out+=`<text x="${x(i)}" y="233" text-anchor="middle">${i>0?'+':''}${i}%</text>`;const py=s=>y((mark*(1+s/100)-a.entry)*q*dir),path=`M 55 ${py(-20)} L 665 ${py(20)}`;
 out+=`<path d="${path} L 665 207 L 55 207 Z" fill="url(#fade)"/><path d="${path}" stroke="#b9f879" stroke-width="2" fill="none"/><line x1="${x(shock)}" x2="${x(shock)}" y1="25" y2="209" stroke="#8a9caa" stroke-dasharray="3 5"/><circle cx="${x(shock)}" cy="${py(shock)}" r="5" fill="#b9f879"/><text x="55" y="15">计划毛盈亏 / USD</text><text x="665" y="116" text-anchor="end">$0</text>`;const stopShock=(Number($('stop').value)/mark-1)*100;if(Number($('stop').value)>0&&stopShock>=-20&&stopShock<=20)out+=`<line x1="${x(stopShock)}" x2="${x(stopShock)}" y1="25" y2="209" stroke="#ff887d" stroke-dasharray="4 6"/><text x="${x(stopShock)+5}" y="35">STOP</text>`;$('chart').innerHTML=out;
}
function renderAnalysis(now){const a=analysis;definition('bookMetrics',a?[['20 档可完整开仓',a.opening.complete?'是':'否 · 剩余 '+a.opening.unfilled],['预计最差开仓价',usd(a.opening.worst)],['立即反向平仓均价（当前簿）',usd(a.closing.vwap)],['立即往返价差盈亏（未计费）',signed(a.roundTripSpread)],['估计开仓手续费',a.openingFee===null?'不可用 · 需账户费率':usd(a.openingFee)],['预计下单资金预留',result?.metrics?usd(result.metrics.requiredBuyingPower)+' · 保证金及双边手续费预留':'需完整账户评估'],['官方市价保护边界',a.priceBoundExceeded?'超出（计划不可执行）':'未超出 / 须复核']]:[['订单簿评估','需新鲜市场数据及有效数量、杠杆与时长']]);$('depthBands').textContent=a?a.depthBands.map(b=>`标记价 ±${(b.band*100).toFixed(1)}% 内：可见买盘 ${usd(b.bid)} / 卖盘 ${usd(b.ask)}`).join('； ')+'。仅覆盖返回的 20 档，不代表全市场深度。':'—';
 $('fundingAnalysis').textContent=a?.funding?`${$('holdingHours').value} 小时计划内预计 ${a.funding.periods} 次结算，按当前费率恒定估计资金费 ${signed(a.funding.estimate)}。下一次官方结算 ${new Date(a.funding.next).toLocaleString()}。`:'资金费或结算时间不可用，不能填零替代。';$('holdingRows').replaceChildren();if(a)for(const h of [1,8,24,Number($('holdingHours').value)].filter((v,i,arr)=>arr.indexOf(v)===i)){try{const f=analyzeMarket(market,{...plan(),holdingHours:String(h)},account?.fees,now).funding;const row=node('tr');[h+' 小时',f?.periods??'—',f?signed(f.estimate):'不可用',account?.fees&&a.entry!==null?usd((a.entry+Number(market.mark.p))*Number(plan().quantity)*Number(account.fees.takerRate)):'需账户费率'].forEach(v=>row.append(node('td',v)));$('holdingRows').append(row)}catch{}}
 $('scenarioRows').replaceChildren();if(a?.scenarios.length)for(const s of a.scenarios){const row=node('tr');[`${s.change>0?'+':''}${s.change}%`,usd(s.price),signed(s.gross),s.estimatedNet===null?'需账户费率':signed(s.estimatedNet),s.liquidatable?'触及强平条件 · 最终损失未确定':'高于维持保证金'].forEach(v=>row.append(node('td',v)));$('scenarioRows').append(row)}else{const r=node('tr'),c=node('td','需新鲜行情与有效计划参数');c.colSpan=5;r.append(c);$('scenarioRows').append(r)}
}
function renderAccount(p){const positions=fresh(p.positions)&&Array.isArray(p.positions.data?.positions)?p.positions.data.positions:null;table('positionTable',['市场 / 官方模式','数量','入场价','未实现盈亏','隔离余额','官方强平参考价'],positions?.map(r=>[r.symbol+' / '+r.margin_mode,r.size,usd(Number(r.entry_price)),signed(Number(r.upnl)),r.margin_mode==='isolated'?usd(Number(r.iso_balance)):'全仓',r.liquidation_price!==undefined?usd(Number(r.liquidation_price)):'字段缺失'])??null,positions?'官方返回：无持仓':p.positions?.error??'需 API Wallet 授权');
 const orders=fresh(p.openOrders)&&Array.isArray(p.openOrders.data?.orders)?p.openOrders.data.orders:null;table('ordersTable',['市场','方向 / 类型','数量 / 已成交','价格 / 止损价','状态'],orders?.map(o=>[o.Symbol,o.Side+' / '+o.Type,o.Size+' / '+o.Filled,o.Price+' / '+o.StopPrice,o.Status])??null,orders?'官方返回：无挂单':p.openOrders?.error);
 const fills=fresh(p.fillHistory)&&Array.isArray(p.fillHistory.data?.fills)?p.fillHistory.data.fills:null,ordersHistory=fresh(p.orderHistory)&&Array.isArray(p.orderHistory.data?.orders)?p.orderHistory.data.orders:null;
 const rows=[];if(fills)for(const o of fills)rows.push(['成交',o.symbol,o.side,o.size??o.quantity??'字段未返回',o.price??'字段未返回',JSON.stringify(o)]);if(ordersHistory)for(const o of ordersHistory)rows.push(['订单',o.symbol,o.side,o.size,o.status,JSON.stringify(o)]);
 table('historyTable',['记录类型','市场','方向','数量','价格 / 状态','官方记录'],fills||ordersHistory?rows:null,'历史接口不可用或需授权；详情见数据来源');}
function drawHistory(p){const rows=fresh(p.klines)&&Array.isArray(p.klines.data)?p.klines.data:[];const values=rows.map(r=>({time:Number(r[0]),close:Number(r[4])})).filter(r=>Number.isFinite(r.time)&&Number.isFinite(r.close)&&r.close>0);if(values.length<2){$('historyChart').replaceChildren();$('historyHint').textContent='历史 K 线不可用，未生成替代数据。';return}const low=Math.min(...values.map(v=>v.close)),high=Math.max(...values.map(v=>v.close)),range=Math.max(high-low,.01);const path=values.map((v,i)=>(i?'L':'M')+' '+(45+i/(values.length-1)*630).toFixed(2)+' '+(140-(v.close-low)/range*110).toFixed(2)).join(' ');$('historyChart').innerHTML=`<line x1="45" x2="675" y1="145" y2="145" stroke="#29343c"/><path d="${path}" fill="none" stroke="#b9f879" stroke-width="2"/><text x="45" y="170">${time(values[0].time)}</text><text x="675" y="170" text-anchor="end">${time(values.at(-1).time)}</text><text x="45" y="20">${usd(high)}</text>`;$('historyHint').textContent='Strike 官方 mark K 线 close，'+values.length+' 根；仅历史观察，不代表未来。';}

function renderSources(p){$('sourceRows').replaceChildren();for(const name of Object.keys(labels)){const packet=p[name],row=node('tr');row.append(node('td',labels[name]),node('td',packet?.route??PRIVATE_ROUTES[name]??'等待读取'),node('td',packet?.ok?(fresh(packet)?'已读取 · ':'已过期 · ')+time(packet.at):(packet?.error??'尚未读取')));const cell=node('td'),button=node('button','查看','ghost');button.disabled=!packet;button.onclick=()=>{$('rawData').hidden=false;$('rawData').textContent=JSON.stringify({name,origin:client.origin,route:packet.route,status:packet.ok?'OFFICIAL_RESPONSE':'UNAVAILABLE',at:packet.at,data:packet.data??null,error:packet.error??null},null,2)};cell.append(button);row.append(cell);$('sourceRows').append(row)}}
$('connectToggle').onclick=()=>{$('authPanel').hidden=!$('authPanel').hidden};$('disconnect').onclick=()=>{client.disconnect();bundle=null;account=null;result=null;$('authStatus').textContent='已清除当前签名会话。';revision++;render();reloadSession()};
$('keyForm').onsubmit=async e=>{e.preventDefault();const keys={publicKey:$('apiPublicKey').value.trim(),privateKey:$('apiPrivateKey').value.trim()};$('apiPublicKey').value='';$('apiPrivateKey').value='';revision++;bundle=null;$('authStatus').textContent='验证密钥对并读取官方账户…';try{await client.importKeys(keys);keys.privateKey='';keys.publicKey='';await reloadSession();$('authStatus').textContent=account?'✓ 真实账户已读取；当前应用只允许 GET 请求。':'未能完成真实账户核验：'+accountError;}catch(e){$('authStatus').textContent=e.message;render()}finally{keys.privateKey='';keys.publicKey=''}};
$('useLocal').onclick=async()=>{revision++;bundle=null;try{await client.useLocal();await reloadSession();$('authStatus').textContent=account?'✓ 本机签名已连接真实账户。':'账户核验未完成：'+accountError}catch(e){$('authStatus').textContent=e.message}};
async function detect(){await client.detectLocal();$('useLocal').disabled=!client.localConfigured;$('localHint').textContent=client.localConfigured?'本机检测到当前网络的 API Wallet 配置。':'未检测到当前网络的本机密钥配置；在线版可使用右侧当前页导入。'}
$('network').onchange=async()=>{client.disconnect();revision++;client=new StrikeClient({network:$('network').value});bundle=null;market=null;account=null;$('quantity').value='';$('stop').value='';render();await detect();await reloadSession()};$('symbol').onchange=()=>{revision++;bundle=null;market=null;$('quantity').value='';$('stop').value='';render();const retry=()=>{if(busy)setTimeout(retry,100);else load()};retry()};
for(const id of ['stop','stopAmount','holdingHours'])$(id).addEventListener('input',render);for(const id of ['amount','leverage'])$(id).addEventListener('input',()=>{try{applyAmount()}catch{}render()});$('amountBasis').addEventListener('change',()=>{try{applyAmount()}catch{}render()});$('quantity').addEventListener('input',()=>{if(market&&Number($('quantity').value)>0&&Number($('leverage').value)>0){const n=Number($('quantity').value)*Number(market.mark.p);$('amount').value=($('amountBasis').value==='margin'?n/Number($('leverage').value):n).toFixed(2)}render()});$('stopMode').addEventListener('change',render);$('shock').addEventListener('input',drawStress);
for(const s of ['long','short'])$(s).onclick=()=>{side=s;for(const id of ['long','short'])$(id).classList.toggle('selected',id===s);render()};
$('useOfficialLeverage').onclick=()=>{if(account){$('leverage').value=String(account.leverage);render()}};
$('applyAmount').onclick=()=>{try{applyAmount();render()}catch(e){$('actionStatus').textContent=e.message}};$('example').onclick=example;$('refresh').onclick=load;
$('recommend').onclick=()=>{const r=recommendLive(bundle,plan());if(r){$('quantity').value=r.quantity;$('actionStatus').textContent='按真实账户配置推荐，留出 5% 模型风险预算余量；不保证实际亏损上限。';render()}else $('actionStatus').textContent='无法推荐：'+(result?.reasons.map(tr).join('；')??'需完整真实数据')};
$('submit').onclick=async()=>{await load();$('actionStatus').textContent=result?.ok?'✓ 完整评估通过；只针对本次快照，不是交易所订单准入或成交承诺。':'⊘ 完整评估被拦截：'+(result?.reasons.map(tr).join('；')??'数据不可用')};
$('export').onclick=()=>{const data={product:'Strike Guardian',mode:'READ_ONLY_REAL_DATA',exportedAt:new Date().toISOString(),plan:plan(),accountId:account?.accountId??null,assessment:result?{ok:result.ok,reasons:result.reasons,metrics:result.metrics,provenance:result.provenance}:null,marketAnalysis:analysis,officialData:bundle,policy:{riskEquityPercent:1,marginEquityPercent:25,maxLeverage:10,extraRiskBufferBps:10},limitations:['No trading writes','Future prices, fees and liquidity unknown','Stop and liquidation fills not guaranteed','Effective fees derived from official account fields are estimates']};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=node('a');a.href=URL.createObjectURL(blob);a.download='guardian-live-assessment.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
render();await detect();await load();setInterval(load,10000);setInterval(render,1000);
